import fs from 'node:fs/promises';import path from 'node:path';
const root=path.resolve('EVA_PRINT_WEBSITE_BRIEF_2026-10-02');const mats=JSON.parse(await fs.readFile(path.join(root,'02_MATERIALS/materials.en.json')));const man=JSON.parse(await fs.readFile(path.join(root,'09_SOURCES/download-manifest.json')));
for(const m of mats.filter(m=>!m.reference_photos.length&&m.brand==='3DXTECH')){try{let r=await fetch(m.source_url+'.json');if(!r.ok)continue;let p=(await r.json()).product;for(const [i,img]of(p.images||[]).slice(0,2).entries()){const url=img.src;let r=await fetch(url);if(!r.ok||!r.headers.get('content-type')?.startsWith('image/'))continue;const b=Buffer.from(await r.arrayBuffer());const rel='04_REFERENCE_PHOTOS/'+m.id+'/manufacturer-'+i+(path.extname(new URL(url).pathname)||'.jpg');await fs.mkdir(path.dirname(path.join(root,rel)),{recursive:true});await fs.writeFile(path.join(root,rel),b);m.reference_photos.push({path:rel,url,source_url:m.source_url,caption:p.title+' — manufacturer product reference, not an EVA PRINT project.',rights:'reference_only_permission_required'});man.push({path:rel,url,source_page:m.source_url,kind:'image',status:'downloaded',bytes:b.length,checked_at:'2026-10-02',publication_rights:'reference_only_permission_required'});}}catch(e){console.log(m.id,e.message);}}
const matte=mats.find(m=>m.id==='pla-matte-fiberlogy');try{const r=await fetch(matte.source_url),t=await r.text();const urls=[...new Set([...t.matchAll(/https:\/\/fiberlogy\.com\/[^\s"'<>]+\.(?:webp|png|jpg)/g)].map(m=>m[0]))].filter(u=>/matte.?pla|pla.?matte/i.test(u));for(const [i,url]of urls.slice(0,2).entries()){const r=await fetch(url);if(!r.ok)continue;const b=Buffer.from(await r.arrayBuffer());const rel='04_REFERENCE_PHOTOS/'+matte.id+'/reference-'+i+path.extname(new URL(url).pathname);await fs.mkdir(path.dirname(path.join(root,rel)),{recursive:true});await fs.writeFile(path.join(root,rel),b);matte.reference_photos.push({path:rel,url,source_url:matte.source_url,rights:'reference_only_permission_required'});man.push({path:rel,url,source_page:matte.source_url,kind:'image',status:'downloaded',bytes:b.length,checked_at:'2026-10-02'});}}catch(e){}
await fs.writeFile(path.join(root,'02_MATERIALS/materials.en.json'),JSON.stringify(mats,null,2));await fs.writeFile(path.join(root,'09_SOURCES/download-manifest.json'),JSON.stringify(man,null,2));console.log('Photos cover',mats.filter(m=>m.reference_photos.length).length,'of',mats.length,'grades');
